p='Pools.tsx'
s=open(p).read()
s=s.replace("import type { Person } from '../people/api';\n","import type { Person } from '../people/api';\nimport { downloadCsv } from '../people/ExportPeople';\n",1)
s=s.replace("""      <h3>Pools</h3>
""","""      <h3>Pools</h3>
      <button type="button" data-testid="export-pools"
        onClick={() => {
          void listPools(sheetId).then((fresh) => {
            queryClient.setQueryData(poolsKey(sheetId), fresh);
            downloadPools(fresh);
          });
        }}>
        Export pools
      </button>
""",1)
s=s.replace("""/** The select's value""","""/** Downloads the pools as a CSV file: one line per member, pools and members in the order added, a pool
 *  member as pool:<name> and its cut as shown (empty when none). */
function downloadPools(pools: Pool[]) {
  downloadCsv('pools.csv', [['pool', 'member', 'share', 'cut'],
    ...pools.flatMap((p) => p.members.map((m) => [p.name, m.poolId !== null ? `pool:${m.name}` : m.name, m.share, m.cut]))]);
}

/** The select's value""",1)
open(p,'w').write(s)
EOF
